NEWF = json.loads(r"""{"inc/dejavoo.php": "<?php\n/* (2.99.638a - LENH-638 A, anh Logan 03/11 09:51) DEJAVOO P5 \u2013 SPIn Cloud REST API (v2). Only the calls; nothing in the app uses them yet (638b HQ setup,\n   638c Checkout, 638d void / refund, 638e close day). OFF by default (setting dv_on = '0').\n   Field names from the public docs (docs.ipospays.com/spin-specification/RestApi, read 03/11): POST /v2/Payment/Sale | Return | Void | TipAdjust | Status |\n   Settle | AbortTransaction, GET /v2/Common/TerminalStatus?request.tpn=&request.authkey=. Sandbox https://test.spinpos.net, live https://spinpos.net.\n   Every answer has GeneralResponse {ResultCode \"0\" ok / \"1\" terminal / \"2\" SPIn Proxy, StatusCode \"0000\" approved ... 1xxx terminal, 2xxx proxy, Message}.\n   SAFETY:\n   - only sandbox unless setting dv_env = 'live' (anh Logan turns it on later); the test kit points cfg()['dv_base'] at its fake server (config, never a setting).\n   - Register ID / Auth Key kept ENCRYPTED (ad_enc, like the Android password); never written to a log, the audit, the screen or an error text.\n   - \"paid\" ONLY with ResultCode 0 + StatusCode 0000 (0001 partial approval is NOT paid). No answer / timeout / terminal in use -> Status by the SAME\n     ReferenceId before anything else: approved there = paid; not found = safe to try again; anything else = \"check the P5\" (never a 2nd charge).\n   - the Dejavoo journal (setting dv_log, last 300): time, call, ReferenceId, amounts, result, Last4, card type, AuthCode, PNReferenceId \u2013 never the card number. */\ndeclare(strict_types=1);\nif (!function_exists('ad_enc')) require_once __DIR__ . '/android.php';\n\nconst DV_URL = ['uat' => 'https://test.spinpos.net', 'live' => 'https://spinpos.net'];\nconst DV_WAIT = 120;          // SPIn Proxy default (s); the customer taps / inserts the card in this time\nconst DV_PAY_TYPE = 'Card';   // the P5 asks credit / debit itself (docs: Credit | Debit | ... | Card)\n\nfunction dv_on(): bool { return setting('dv_on') === '1'; }\nfunction dv_env(): string { return setting('dv_env') === 'live' ? 'live' : 'uat'; }\nfunction dv_base(): string { $b = trim((string)(cfg()['dv_base'] ?? '')); return $b !== '' ? rtrim($b, '/') : DV_URL[dv_env()]; }\n/** The terminal of this salon: TPN (not secret) + Register ID + Auth Key (encrypted). */\nfunction dv_creds(): array { return ['tpn' => trim((string)setting('dv_tpn')), 'reg' => ad_dec((string)setting('dv_reg')), 'auth' => ad_dec((string)setting('dv_auth'))]; }\nfunction dv_ready(): bool { $c = dv_creds(); return ($c['tpn'] !== '' || $c['reg'] !== '') && $c['auth'] !== ''; }\n/** HQ (638b): save the codes. '' = keep the one saved; null = remove. Returns what may be shown (\"\u2026abcd\"). */\nfunction dv_set_creds(?string $tpn, ?string $reg, ?string $auth): array {\n    $t = $tpn === null ? null : preg_replace('/\\D+/', '', $tpn); $reg = $reg === null ? null : trim($reg); $auth = $auth === null ? null : trim($auth);\n    if ($t !== null && $t !== '' && (strlen($t) < 10 || strlen($t) > 12)) throw new InvalidArgumentException('TPN: 10\u201312 digits.'); // everything checked BEFORE anything is saved\n    if ($reg !== null && $reg !== '' && (strlen($reg) < 2 || strlen($reg) > 50)) throw new InvalidArgumentException('Register ID: 2\u201350 characters.');\n    if ($auth !== null && $auth !== '' && strlen($auth) !== 10) throw new InvalidArgumentException('Auth Key: exactly 10 characters.');\n    if ($t !== null && ($t !== '' || $tpn === null)) set_setting('dv_tpn', (string)$t);\n    foreach (['dv_reg' => $reg, 'dv_auth' => $auth] as $k => $v) { if ($v === null) set_setting($k, ''); elseif ($v !== '') set_setting($k, ad_enc($v)); }\n    return dv_shown();\n}\nfunction dv_shown(): array { $c = dv_creds(); $m = fn($s) => $s === '' ? '' : '\u2026' . substr($s, -4); return ['tpn' => $c['tpn'], 'reg' => $m($c['reg']), 'auth' => $m($c['auth']), 'env' => dv_env(), 'on' => dv_on()]; }\n/** One ReferenceId per payment try (alphanumeric, 1\u201350, unique in the batch): NF + time + random. */\nfunction dv_new_ref(): string { return 'NF' . date('ymdHis') . strtoupper(bin2hex(random_bytes(3))); }\n\n/** The HTTP call. Never throws; never puts the codes in the result. */\nfunction dv_http(string $method, string $path, array $body, int $wait): array {\n    $c = dv_creds(); $url = dv_base() . $path;\n    if ($method === 'GET') { $url .= '?' . http_build_query(array_filter(['request.tpn' => $c['tpn'], 'request.registerId' => $c['tpn'] === '' ? $c['reg'] : '', 'request.authkey' => $c['auth']], fn($v) => $v !== '')); $data = null; }\n    else { $body += array_filter(['Tpn' => $c['tpn'], 'RegisterId' => $c['tpn'] === '' ? $c['reg'] : '', 'Authkey' => $c['auth']], fn($v) => $v !== ''); $data = json_encode($body); }\n    $ch = curl_init($url);\n    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_CONNECTTIMEOUT => 10, CURLOPT_TIMEOUT => $wait + (int)(cfg()['dv_slack'] ?? 15) /* the proxy answers by itself at its timeout; the test kit makes this short */, CURLOPT_CUSTOMREQUEST => $method,\n        CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json']] + ($data !== null ? [CURLOPT_POSTFIELDS => $data] : []));\n    $raw = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE); $errno = curl_errno($ch); curl_close($ch);\n    if ($raw === false || $errno) return ['net' => true, 'http' => $code, 'j' => null, 'err' => $errno === CURLE_OPERATION_TIMEDOUT ? 'timeout' : 'no answer'];\n    $j = json_decode((string)$raw, true);\n    return ['net' => false, 'http' => $code, 'j' => is_array($j) ? $j : null, 'err' => is_array($j) ? '' : 'bad answer (HTTP ' . $code . ')'];\n}\n/** Answer -> one plain result. status: approved | partial | declined | cancelled | busy | timeout | not_found | not_connected | auth | error | unknown */\nfunction dv_norm(array $h): array {\n    $o = ['status' => 'unknown', 'code' => '', 'msg' => $h['err'] ?? '', 'net' => !empty($h['net'])];\n    if (!empty($h['net'])) { $o['status'] = $h['err'] === 'timeout' ? 'timeout' : 'unknown'; return $o; }\n    $j = $h['j']; if (!is_array($j)) return $o;\n    $g = (array)($j['GeneralResponse'] ?? []); $rc = (string)($g['ResultCode'] ?? ''); $sc = (string)($g['StatusCode'] ?? '');\n    $o['code'] = $sc; $o['msg'] = trim((string)($g['Message'] ?? '') . ' ' . (string)($g['DetailedMessage'] ?? ''));\n    $o['status'] = $rc === '0' && $sc === '0000' ? 'approved' : ($rc === '0' && $sc === '0001' ? 'partial' : (match ($sc) {\n        '1015', '1016', '1019' => 'declined', '1012' => 'cancelled', '1000', '2008' => 'busy', '2007' => 'timeout', '1001', '2009' => 'not_found',\n        '2001', '2004', '2005', '2011' => 'not_connected', '1009', '2002', '2003' => 'auth', default => 'error' }));\n    $am = (array)($j['Amounts'] ?? []); $cd = (array)($j['CardData'] ?? []);\n    $o += ['ref' => (string)($j['ReferenceId'] ?? ''), 'auth_code' => (string)($j['AuthCode'] ?? ''), 'pnref' => (string)($j['PNReferenceId'] ?? ''), 'rrn' => (string)($j['RRN'] ?? ''),\n        'last4' => preg_match('/^\\d{4}$/', (string)($cd['Last4'] ?? '')) ? (string)$cd['Last4'] : '', 'card' => (string)(($cd['CardBrand'] ?? '') !== '' ? $cd['CardBrand'] : ($cd['CardType'] ?? '')),\n        'entry' => (string)($cd['EntryType'] ?? ''), 'type' => (string)($j['TransactionType'] ?? ''), 'pay_type' => (string)($j['PaymentType'] ?? ''), 'batch' => (string)($j['BatchNumber'] ?? ''),\n        'txn_no' => (string)($j['TransactionNumber'] ?? ''), 'voided' => !empty($j['Voided']), 'amount' => isset($am['Amount']) ? (float)$am['Amount'] : null,\n        'tip' => isset($am['TipAmount']) ? (float)$am['TipAmount'] : null, 'total' => isset($am['TotalAmount']) ? (float)$am['TotalAmount'] : null,\n        'delay' => isset($g['DelayBeforeNextRequest']) ? (int)$g['DelayBeforeNextRequest'] : null];\n    return $o;\n}\n/** The Dejavoo journal (no codes, no card number). */\nfunction dv_log(string $op, string $ref, array $r, array $x = []): void {\n    $l = json_decode((string)setting('dv_log'), true); $l = is_array($l) ? $l : [];\n    $l[] = array_filter(['at' => now_str(), 'op' => $op, 'ref' => $ref, 'env' => dv_env(), 'status' => $r['status'] ?? '', 'code' => $r['code'] ?? '', 'msg' => mb_substr((string)($r['msg'] ?? ''), 0, 120),\n        'amount' => $x['amount'] ?? null, 'tip' => $x['tip'] ?? null, 'last4' => $r['last4'] ?? '', 'card' => $r['card'] ?? '', 'auth_code' => $r['auth_code'] ?? '', 'pnref' => $r['pnref'] ?? '', 'by' => $x['by'] ?? ''], fn($v) => $v !== '' && $v !== null);\n    set_setting('dv_log', json_encode(array_slice($l, -300), JSON_UNESCAPED_UNICODE));\n}\nfunction dv_call(string $op, string $method, string $path, array $body, int $wait, array $x = []): array {\n    if (!dv_ready()) { $r = ['status' => 'auth', 'code' => '', 'msg' => 'The card terminal is not set up (NailFlow sets it up).', 'net' => false]; dv_log($op, (string)($body['ReferenceId'] ?? ''), $r, $x); return $r; }\n    if ($method === 'POST') $body['SPInProxyTimeout'] = max(1, min(720, $wait));\n    $r = dv_norm(dv_http($method, $path, $body, $wait)); dv_log($op, (string)($body['ReferenceId'] ?? ''), $r, $x); return $r;\n}\nfunction dv_amt(float $a): float { return round(max(0.0, $a), 2); }\n\n/* ---------- the calls ---------- */\nfunction dv_status(string $ref, int $wait = 30): array { return dv_call('status', 'POST', '/v2/Payment/Status', ['PaymentType' => DV_PAY_TYPE, 'ReferenceId' => $ref, 'PrintReceipt' => 'No', 'GetReceipt' => 'No'], $wait); }\n/** Sale on the P5. ALWAYS returns a result that says whether the money was taken:\n    paid = true only when approved (here or by Status after a lost answer); retry_ok = true when it is sure nothing was charged. */\nfunction dv_sale(float $amount, float $tip, string $ref, string $invoice = '', int $wait = DV_WAIT): array {\n    $x = ['amount' => dv_amt($amount), 'tip' => dv_amt($tip)];\n    $r = dv_call('sale', 'POST', '/v2/Payment/Sale', array_filter(['Amount' => dv_amt($amount), 'TipAmount' => $tip > 0 ? dv_amt($tip) : null, 'PaymentType' => DV_PAY_TYPE, 'ReferenceId' => $ref,\n        'InvoiceNumber' => mb_substr($invoice, 0, 50), 'PrintReceipt' => 'No', 'GetReceipt' => 'No', 'CaptureSignature' => false, 'GetExtendedData' => false], fn($v) => $v !== null && $v !== ''), $wait, $x);\n    return dv_settle_answer($r, $ref);\n}\n/** After a sale / return: an unsure answer is checked by Status (same ReferenceId) before anyone may try again. */\nfunction dv_settle_answer(array $r, string $ref): array {\n    if (in_array($r['status'], ['timeout', 'unknown', 'busy', 'error'], true)) {\n        $s = dv_status($ref);\n        if ($s['status'] === 'approved') return $s + ['paid' => true, 'retry_ok' => false, 'checked' => true];\n        if ($s['status'] === 'not_found') return $r + ['paid' => false, 'retry_ok' => true, 'checked' => true];\n        return $r + ['paid' => false, 'retry_ok' => false, 'checked' => true, 'unsure' => true]; // nobody knows yet: look at the P5 / its report before trying again\n    }\n    if ($r['status'] === 'partial') return $r + ['paid' => false, 'retry_ok' => false, 'checked' => false, 'unsure' => true]; // part of the money taken: never \"paid\", never charged again \u2013 void it on the P5\n    return $r + ['paid' => $r['status'] === 'approved', 'retry_ok' => in_array($r['status'], ['declined', 'cancelled', 'not_connected', 'auth'], true), 'checked' => false];\n}\n/** Money back WITHOUT the original (a new ReferenceId; the card is presented again). */\nfunction dv_return(float $amount, string $ref, int $wait = DV_WAIT): array {\n    $r = dv_call('return', 'POST', '/v2/Payment/Return', ['Amount' => dv_amt($amount), 'PaymentType' => DV_PAY_TYPE, 'ReferenceId' => $ref, 'PrintReceipt' => 'No', 'GetReceipt' => 'No'], $wait, ['amount' => dv_amt($amount)]);\n    return dv_settle_answer($r, $ref);\n}\n/** Cancel a sale of today's open batch (its own ReferenceId + its amount). ok only when approved. */\nfunction dv_void(float $amount, string $ref, int $wait = 60): array {\n    $r = dv_call('void', 'POST', '/v2/Payment/Void', ['Amount' => dv_amt($amount), 'PaymentType' => DV_PAY_TYPE, 'ReferenceId' => $ref, 'PrintReceipt' => 'No', 'GetReceipt' => 'No'], $wait, ['amount' => dv_amt($amount)]);\n    return $r + ['ok' => $r['status'] === 'approved'];\n}\n/** Tip after the sale (Replace = the tip becomes this amount). */\nfunction dv_tip_adjust(float $amount, float $tip, string $ref, int $wait = 60): array {\n    $r = dv_call('tip', 'POST', '/v2/Payment/TipAdjust', ['Amount' => dv_amt($amount), 'TipAmount' => dv_amt($tip), 'TipIndicator' => 'Replace', 'PaymentType' => DV_PAY_TYPE, 'ReferenceId' => $ref], $wait, ['amount' => dv_amt($amount), 'tip' => dv_amt($tip)]);\n    return $r + ['ok' => $r['status'] === 'approved'];\n}\n/** Stop the payment waiting on the P5 (the customer walked away). Then Status tells whether it went through anyway. */\nfunction dv_abort(string $ref, int $wait = 30): array { $r = dv_call('abort', 'POST', '/v2/Payment/AbortTransaction', ['ReferenceId' => $ref], $wait); return $r + ['ok' => $r['status'] === 'approved']; }\n/** Close the batch (settlement can take up to 420 s). totals per application when the P5 sends them. */\nfunction dv_settle(string $ref, int $wait = 420): array {\n    if (!dv_ready()) return dv_call('settle', 'POST', '/v2/Payment/Settle', [], $wait) + ['ok' => false, 'totals' => []];\n    $h = dv_http('POST', '/v2/Payment/Settle', ['ReferenceId' => $ref, 'SettlementType' => 'Close', 'GetReceipt' => false, 'SPInProxyTimeout' => min(720, $wait)], $wait); $r = dv_norm($h);\n    $t = []; foreach ((array)($h['j']['SettleDetails'] ?? []) as $d) { $x = (array)($d['TransactionsReports'] ?? []);\n        $t[] = ['batch' => (string)($d['BatchNumber'] ?? ''), 'count' => (int)($x['TransactionsCount'] ?? 0), 'sale' => (float)($x['SaleAmount'] ?? 0), 'return' => (float)($x['ReturnAmount'] ?? 0), 'void' => (float)($x['VoidAmount'] ?? 0), 'total' => (float)($x['TotalAmount'] ?? 0)]; }\n    dv_log('settle', $ref, $r); return $r + ['ok' => $r['status'] === 'approved', 'totals' => $t];\n}\n/** Is the P5 connected to SPIn Proxy? ['online' => bool, 'status' => text]. */\nfunction dv_terminal_status(int $wait = 20): array {\n    if (!dv_ready()) return ['online' => false, 'status' => 'not set up', 'msg' => ''];\n    $h = dv_http('GET', '/v2/Common/TerminalStatus', [], $wait); $j = (array)($h['j'] ?? []);\n    $st = (string)($j['TerminalStatus'] ?? ($h['net'] ? 'no answer' : 'unknown')); $r = ['online' => strcasecmp($st, 'Online') === 0, 'status' => $st, 'msg' => mb_substr((string)($j['ErrorDescription'] ?? ''), 0, 120)];\n    dv_log('terminal', '', ['status' => $r['online'] ? 'online' : 'offline', 'msg' => $st]); return $r;\n}\n"}""")
